using Microsoft.AspNetCore.RateLimiting; using Microsoft.EntityFrameworkCore; using TrootWindow.Api.Data; var b=WebApplication.CreateBuilder(args); b.Services.AddControllers(); b.Services.AddDbContext<AppDbContext>(o=>o.UseSqlServer(b.Configuration.GetConnectionString("DefaultConnection"))); b.Services.AddRateLimiter(o=>o.AddFixedWindowLimiter("public",x=>{x.PermitLimit=60;x.Window=TimeSpan.FromMinutes(1);x.QueueLimit=0;})); b.Services.AddCors(o=>o.AddPolicy("frontend",p=>p.WithOrigins(b.Configuration.GetSection("Cors:Origins").Get<string[]>()??[]).AllowAnyHeader().AllowAnyMethod())); var app=b.Build(); app.UseHttpsRedirection(); app.UseRateLimiter(); app.UseCors("frontend"); app.MapControllers(); using(var s=app.Services.CreateScope()){var db=s.ServiceProvider.GetRequiredService<AppDbContext>(); await db.Database.MigrateAsync();} app.Run();